interface.signature:
type SSEEvent =
  | { type: 'status'; message: string }
  | { type: 'token'; content: string }
  | { type: 'tool_call'; id?: string; name: string; args: object }
  | { type: 'tool_result'; tool_call_id: string; result?: object; error?: string }
  | { type: 'done'; tokens_used: { prompt: number; completion: number } }
  | { type: 'error'; message: string; code: string };

interface ToolCallCardProps {
  toolName: string;
  args: Record<string, any>;
  status: 'running' | 'success' | 'error';
  result?: any;
  error?: string;
}

interface ToolState {
  activeTools: Array<{
    id: string;
    name: string;
    args: Record<string, any>;
    status: 'running' | 'success' | 'error';
    result?: any;
    error?: string;
  }>;
  addToolCall: (tool: ToolState['activeTools'][0]) => void;
  updateToolCall: (id: string, updates: Partial<ToolState['activeTools'][0]>) => void;
  clearTools: () => void;
}
